
# Aroeira - approximate 3D reconstruction from perspective renders
# Generated by ChatGPT. Units: meters converted to inches for SketchUp.
model = Sketchup.active_model
model.start_operation("Aroeira Approx Model", true)
ents = model.active_entities

def m(v); v * 39.3700787402; end

def mat(model, name, rgb)
  mtl = model.materials[name] || model.materials.add(name)
  mtl.color = Sketchup::Color.new(*rgb)
  mtl
end

WHITE = mat(model, "Render branco", [224,219,204])
STONE = mat(model, "Arenito castanho claro", [176,143,96])
WOOD  = mat(model, "Madeira", [106,62,33])
ROOF  = mat(model, "Telha plana terracota", [156,62,31])
GLASS = mat(model, "Vidro escuro", [46,67,74])
COPPER= mat(model, "Cobre", [165,80,38])
GRASS = mat(model, "Relva", [60,105,47])
POOL  = mat(model, "Agua piscina", [54,150,190])

def box(ents, name, x,y,z,w,d,h, material)
  g = ents.add_group
  g.name = name
  e = g.entities
  pts = [[x,y,z],[x+w,y,z],[x+w,y+d,z],[x,y+d,z]].map{|p| Geom::Point3d.new(m(p[0]),m(p[1]),m(p[2]))}
  face = e.add_face(pts)
  face.reverse! if face.normal.z < 0
  face.pushpull(m(h))
  g.material = material
  g
end

def panel_y(ents, name, x,y,z,w,h,t, material)
  box(ents,name,x,y-t/2.0,z,w,t,h,material)
end

def roof_shed(ents, name, x,y,z,w,d,t,rise, material)
  g=ents.add_group
  g.name=name
  e=g.entities
  p=[
    [x,y,z],[x+w,y,z],[x+w,y+d,z+rise],[x,y+d,z+rise],
    [x,y,z+t],[x+w,y,z+t],[x+w,y+d,z+rise+t],[x,y+d,z+rise+t]
  ].map{|a| Geom::Point3d.new(m(a[0]),m(a[1]),m(a[2]))}
  faces=[[0,1,2,3],[4,7,6,5],[0,4,5,1],[1,5,6,2],[2,6,7,3],[3,7,4,0]]
  faces.each{|ii| e.add_face(ii.map{|j| p[j]})}
  g.material=material
  g
end

# terrain
box(ents,"Terrain",-10,-16,-0.25,35,28,0.20,GRASS)

# house
box(ents,"GF Main",0,0,0,18,6,3.0,WHITE)
box(ents,"GF Left Wing",-5,0,0,5.5,8,3.0,STONE)
box(ents,"UF Main",0.5,1.0,3.0,17.0,4.5,2.8,WHITE)
box(ents,"UF Left",-4.5,1.0,3.0,5.0,4.5,2.8,STONE)
box(ents,"Upper Timber Band",0.5,-0.05,3.35,17.0,0.18,1.65,WOOD)
box(ents,"Stone Pier",5.2,-0.15,0,1.6,0.7,3.2,STONE)

# veranda and roofs
roof_shed(ents,"Veranda Roof",6,-4.2,3.0,12,4.2,0.22,0.18,ROOF)
[6.2,9.2,12.2,15.2,17.7].each_with_index{|cx,i| box(ents,"Veranda Column #{i}",cx,-4.0,0,0.18,0.18,3.0,WOOD)}
roof_shed(ents,"Main Roof",0.2,0.5,5.8,17.6,5.2,0.25,0.25,ROOF)
roof_shed(ents,"Left Roof",-4.8,0.5,5.8,5.4,5.2,0.25,0.25,ROOF)

# balcony
box(ents,"Balcony",-4.2,-1.5,2.95,4.5,1.5,0.18,WOOD)

# exterior stairs
6.times{|n| box(ents,"Step #{n}",-6.0-n*0.15,1.2+n*0.65,n*0.20,2.3,0.7,0.20,STONE)}

# garden façade glazing
[[0.8,2.4],[3.6,1.8],[7.2,2.4],[10.4,2.2],[13.4,2.5]].each_with_index{|a,i|
  panel_y(ents,"GF Glass #{i}",a[0],-0.03,0.45,a[1],2.2,0.08,GLASS)
}
[[1.0,1.6],[4.2,1.3],[7.0,1.5],[10.0,1.5],[13.2,1.6]].each_with_index{|a,i|
  panel_y(ents,"UF Glass #{i}",a[0],0.95,3.55,a[1],1.35,0.08,GLASS)
}
panel_y(ents,"Front Strip Window",1.0,6.03,3.8,14.5,0.8,0.08,GLASS)
panel_y(ents,"Garage Door",-4.6,8.02,0.3,3.5,2.3,0.10,WOOD)

# pool
box(ents,"Pool Water",8,-12,0.05,10,4.5,0.10,POOL)
box(ents,"Pool Deck L",7.5,-12.5,0,0.4,5.5,0.12,WOOD)
box(ents,"Pool Deck R",18.0,-12.5,0,0.4,5.5,0.12,WOOD)
box(ents,"Pool Deck Top",7.5,-12.5,0,10.9,0.4,0.12,WOOD)
box(ents,"Pool Deck Bottom",7.5,-7.4,0,10.9,0.4,0.12,WOOD)

# copper pipes as vertical cylinders
[[-4.9,0.2,6.3],[17.7,5.5,6.2]].each_with_index{|a,i|
  g=ents.add_group
  g.name="Copper Pipe #{i}"
  c=g.entities.add_circle(Geom::Point3d.new(m(a[0]),m(a[1]),0), Z_AXIS, m(0.09), 18)
  f=g.entities.add_face(c)
  f.pushpull(m(a[2]))
  g.material=COPPER
}

# set a useful camera
eye = Geom::Point3d.new(m(28),m(-28),m(18))
target = Geom::Point3d.new(m(6),m(-1),m(2.5))
model.active_view.camera = Sketchup::Camera.new(eye,target,Z_AXIS)
model.active_view.zoom_extents

model.commit_operation
UI.messagebox("Modelo Aroeira criado. Reconstrução aproximada baseada nas perspetivas do PDF; guardar agora como .skp.")
